/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import java.util.ArrayList;import java.util.Arrays;import java.util.List;import org.springframework.util.StringUtils;import page2020.util.EmptyUtil;import page2020.view.Value;public class C3font {	public static final class Attr {		public static final String font = "font";		public static final String family = "font-family";		public static final String style = "font-style";		public static final String weight = "font-weight";		public static final String variant = "font-variant";		public static final String size = "font-size";			}	public static final class Family {		public static final String serif = "serif";		public static final String sans = "sans-serif";		public static final String mono = "monospace";	}	public static final class Weight {		public static final String normal = "normal";		public static final String bold = "bold";		public static final String bolder = "bolder";		public static final String lighter = "lighter";	}	public Value font(String shorthand) {		return new Value().name(Attr.font).text(shorthand);	}	public Value family(String... familyNames) {		List<String> families = new ArrayList<String>();		if (EmptyUtil.not(familyNames)) {			Arrays.asList(familyNames).forEach(item -> {				families.add(item.contains(" ") ? ("'" + item + "'") : item);			});		}		return new Value().name(Attr.family).text(StringUtils.collectionToCommaDelimitedString(families));	}	public Value italic(boolean italic) {		String value = italic ? "italic" : "normal";		return new Value().name(Attr.style).text(value);	}	public Value weight(String weight) {		return new Value().name(Attr.weight).text(weight);	}	public Value weight(int number) {		number = (number >= 100 && number <= 900) ? number : 500;		return new Value().name(Attr.weight).text(String.valueOf(number));	}	public Value variant(boolean variant) {		String value = variant ? "small-caps" : "normal";		return new Value().name(Attr.variant).text(value);	}	public Value size(String pixels) {		return new Value().name(Attr.size).text(pixels);	}}